@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--gold:#e5b969;--cream:#f3e8ce;--muted:#a9a7ab;--ink:#090b18;--red:#bf4053}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--cream);font-family:'DM Sans',sans-serif;touch-action:none}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#090b18}#scene{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,transparent 38%,rgba(4,5,13,.4) 100%),linear-gradient(0deg,rgba(5,7,17,.6),transparent 33%,rgba(6,7,15,.16))}.grain{position:absolute;inset:-50%;pointer-events:none;opacity:.08;z-index:2;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");animation:grain .22s steps(2) infinite}@keyframes grain{0%{transform:translate(0,0)}50%{transform:translate(2%,-1%)}100%{transform:translate(-1%,2%)}}.hidden{display:none!important}.title-screen,.ending{position:absolute;inset:0;z-index:3;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:8vw 11vw;background:linear-gradient(90deg,rgba(6,8,18,.91),rgba(6,8,18,.63) 42%,transparent 78%)}.title-screen:after{content:'';position:absolute;z-index:-1;left:8vw;top:17%;bottom:17%;width:1px;background:linear-gradient(transparent,var(--gold),transparent);opacity:.6}.title-kicker,.title-foot{font-size:10px;letter-spacing:.24em;font-weight:700;color:var(--gold);display:flex;align-items:center;gap:12px}.title-kicker i,.intro-caption i{height:1px;width:34px;background:var(--gold);display:inline-block}.bat-mark{font-size:20px;color:var(--gold);line-height:1}.title-screen h1{font-family:'Barlow Condense