#090b1877;padding:8px 11px;font-size:13px;letter-spacing:.1em;cursor:pointer}.sound-btn span{font-size:8px;margin-left:4px}.objective{position:absolute;z-index:3;left:4vw;top:105px;display:flex;align-items:center;gap:11px;padding:12px 16px 12px 12px;background:linear-gradient(90deg,#090b18d9,#090b1880);border-left:2px solid var(--gold);backdrop-filter:blur(8px)}.objective-icon{font-size:17px;color:var(--gold)}.objective small{font-size:8px;margin-bottom:4px}.objective b{font:600 16px 'Barlow Condensed',sans-serif;letter-spacing:.06em}.prompt{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:9px;padding:9px 13px;background:#090b18dc;border:1px solid #dfb86c88;font:700 10px 'Barlow Condensed',sans-serif;letter-spacing:.18em;box-shadow:0 4px 20px #0008}.keycap{font:700 11px 'DM Sans';color:#16131a;background:var(--gold);padding:4px 6px;border-radius:2px}.dialogue{position:absolute;z-index:5;bottom:0;left:0;right:0;min-height:180px;padding:25px max(8vw,30px) 25px;background:linear-gradient(0deg,#070914f5,#080a17ef);border-top:1px solid #e1b86658;box-shadow:0 -16px 44px #0005}.speaker-line{display:flex;align-items:center;gap:9px;color:var(--gold);font:700 10px 'Barlow Condensed',sans-serif;letter-spacing:.2em}.speaker-dot{width:7px;height:7px;border-radius:50%;background:var(--gold);box-shadow:0 0 12px var(--gold)}.dialogue-rule{height:1px;width:min(16vw,180px);background:#8a724a66}.speaker-line small{font:500 8px 'DM Sans';color:#777883;letter-spacing:.13em}.dialogue p{font-size:clamp(15px,2vw,21px);line-height:1.5;margin:13px 0 12px;color:#f6eee0;max-width:780px}.dialogue button{position:absolute;right:max(8vw,30px);bottom:24px;border:0;background:transparent;color:var(--gold);font:700 10px 'Barlow Condensed';letter-spacing:.16em;cursor:pointer}.dialogue button span{font-size:17px;margin-left:7px}.controls{position:absolute;z-index:4;left:0;right:0;bottom:18px;height:140px;pointer-events:none}.move-pad{position:absolute;left:24px;bottom:0;width:132px;height:132px;pointer-events:auto}.pad{position:absolute;width:42px;height:42px;border-radius:50%;background:#101322b8;border:1px solid #e3c48477;color:#eee0c7;font-size:13px;touch-action:none;backdrop-filter:blur(5px)}.pad:active,.pad.active{background:#d4a959aa;color:#111}.pad.up{left:45px;top:0}.pad.down{left:45px;bottom:0}.pad.left{left:0;top:45px}.pad.right{right:0;top:45px}.pad-center{position:absolute;inset:47px 43px;display:grid;place-items:center;font-size:7px;letter-spacing:.1em;color:#aaa9b1;pointer-events:none}.action-btn{position:absolute;right:25px;bottom:14px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;width:68px;height:68px;border:1px solid #e3c48499;border-radius:50%;background:#111422cc;color:var(--gold);pointer-events:auto;touch-action:none}.action-btn span{font-size:22px;line-height:20px}.action-btn small{font:700 7px 'Barlow Condensed';letter-spacing:.12em}.intro-caption{position:absolute;z-index:3;left:50%;bottom:10%;transform:translateX(-50%);display:flex;align-items:center;gap:11px;white-space:nowrap;font:700 10px 'Barlow Condensed';letter-spacing:.2em;text-shadow:0 2px 6px #000}.intro-caption span{color:var(--gold)}.corner-note{position:absolute;z-index:3;right:22px;bottom:16px;font-size:8px;letter-spacing:.14em;color:#d9d4c288;pointer-events:none}.corner-note span{color:var(--gold);padding:0 5px}.loading{position:absolute;z-index:10;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;background:#090b18;color:var(--gold);font:700 11px 'Barlow Condensed';letter-spacing:.22em;transition:opacity .7s}.loader-mark{font-size:35px;animation:pulse 1.5s infinite}.loading i{width:85px;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);animation:load 1.2s infinite}@keyframes pulse{50%{opacity:.35;transform:scale(.9)}}@keyframes load{50%{transform:scaleX(.45);opacity:.5}}.ending{align-items:center;text-align:center;background:radial-gradient(ellipse,#0c1024dc,#070914f2 70%)}.end-symbol{font-size:36px;color:var(--gold);margin-bottom:16px}.ending>small{font-size:9px;letter-spacing:.24em;color:var(--gold)}.ending h2{font:900 clamp(42px,8vw,88px)/.9 'Barlow Condensed';margin:20px 0;color:#fff1d7}.ending h2 em{font-size:.55em;letter-spacing:.18em;color:var(--gold);font-style:normal}.ending p{font-size:14px;color:#aaa9af;margin:10px 0 30px}.ending .primary-btn{text-align:center}.ending .primary-btn b{float:none;margin-left:18px}
