247: function applyInput(dt) {
248:   if (!player || state !== 'play') return;
249:   const forward = (keys.KeyW || keys.ArrowUp || move.up ? 1 : 0) - (keys.KeyS || keys.ArrowDown || move.down ? 1 : 0);
250:   const sideways = (keys.KeyD || keys.ArrowRight || move.right ? 1 : 0) - (keys.KeyA || keys.ArrowLeft || move.left ? 1 : 0);
251:   // The theater lobby lies ahead at +Z; the avenue/car route runs toward -Z.
252:   const vector = new THREE.Vector3(sideways, 0, stage === 'theater' ? forward : -forward);
253:   if (vector.lengthSq()) {
254:     vector.normalize().applyAxisAngle(new THREE.Vector3(0, 1, 0), camAngle);
255:     const speed = 3.65 * dt;
256:     player.position.x = THREE.MathUtils.clamp(player.position.x + vector.x * speed, -7.3, 7.3);
257:     player.position.z = THREE.MathUtils.clamp(player.position.z + vector.z * speed, stage === 'theater' ? -13.6 : -12.5, stage === 'theater' ? 13 : 10.5);
258:     // Actor models face their local -Z axis.
259:     player.rotation.y = Math.atan2(-vector.x, -vector.z);
260:   }
261:   if (stage === 'theater' && parents.length) {
262:     // Thomas and Martha walk ahead toward the lobby, always keeping Bruce in sight.
263:     for (const [index, actor] of parents.entries()) {
264:       const target = new THREE.Vector3((index === 0 ? -.75 : .75), 0, 12.25 - index * .35);
265:       actor.position.lerp(target, Math.min(1, dt * .34));
266:       actor.rotation.y = Math.PI;
267:     }
268:   }
269:   if (stage === 'city' && parents.length) {
270:     // The family stays together on the sidewalk as Bruce heads for the car.
271:     for (const [index, actor] of parents.entries()) {
272:       const side = index === 0 ? -1.05 : -2.0;
273:       const target = new THREE.Vector3(player.position.x + side, 0, player.position.z + 1.15 + index * .45);
274:       actor.position.lerp(target, Math.min(1, dt * 2.4));
275:       actor.position.x = THREE.MathUtils.clamp(actor.position.x, -6.5, 6.5);
276:       actor.rotation.y = player.rotation.y;
277:     }
278:   }
279:   const threshold = stage === 'theater' ? player.position.z > 11.1 : player.position.distanceTo(car.position) < 2.8;
280:   if (threshold) showPrompt(stage === 'theater' ? 'HEAD TO THE LOBBY' : 'GET IN THE CAR'); else hidePrompt();
