250:   const sideways = (keys.KeyD || keys.ArrowRight || move.right ? 1 : 0) - (keys.KeyA || keys.ArrowLeft || move.left ? 1 : 0);
251:   // The theater lobby lies ahead at +Z; the avenue/car route runs toward -Z.
252:   const vector = new THREE.Vector3(sideways, 0, stage === 'theater' ? forward : -forward);
253:   if (vector.lengthSq()) {
