265:       actor.position.lerp(target, Math.min(1, dt * .34));
266:       actor.rotation.y = Math.PI;
267:     }
268:   }
269:   if (stage === 'city' && parents.length) {
270:     // The family stays together on the sidewalk as Bruce heads for the car.
