272:       const side = index === 0 ? -1.05 : -2.0;
273:       const target = new THREE.Vector3(player.position.x + side, 0, player.position.z + 1.15 + index * .45);
274:       actor.position.lerp(target, Math.min(1, dt * 2.4));
275:       actor.position.x = THREE.MathUtils.clamp(actor.position.x, -6.5, 6.5);
276:       actor.rotation.y = player.rotation.y;
277:     }
278:     if (player.position.distanceTo(car.position) < 2.8) showPrompt('GET IN THE CAR');
